PTX_SOURCE = r'''
.version 7.8
.target sm_120
.address_size 64

.visible .entry matmul_fp16 (
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // -------------------------------------------------
    // Registers
    // -------------------------------------------------
    .reg .pred   %p;
    .reg .u32    %tx, %ty;
    .reg .u32    %bx, %by;
    .reg .u32    %row, %col, %k, %N;
    .reg .u32    %idx;
    .reg .b64    %A, %B, %C, %addr;
    .reg .f16    %a, %b, %c;
    .reg .f32    %af, %bf, %sum;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %N, [N];

    // -------------------------------------------------
    // Thread / block indices
    // -------------------------------------------------
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;

    // -------------------------------------------------
    // Compute global row / column (tile size 16×16)
    // -------------------------------------------------
    mad.lo.u32 %row, %by, 16, %ty;   // row = by*16 + ty
    mad.lo.u32 %col, %bx, 16, %tx;   // col = bx*16 + tx

    // -------------------------------------------------
    // Bounds check
    // -------------------------------------------------
    setp.ge.u32 %p, %row, %N;
    @%p bra DONE;
    setp.ge.u32 %p, %col, %N;
    @%p bra DONE;

    // -------------------------------------------------
    // Accumulator (FP32)
    // -------------------------------------------------
    mov.f32 %sum, 0f0;

    // -------------------------------------------------
    // K‑loop
    // -------------------------------------------------
    mov.u32 %k, 0;
K_LOOP:
    setp.ge.u32 %p, %k, %N;
    @%p bra K_DONE;

    // ---- Load A[row, k] ----------------------------------------------------
    mul.lo.u32 %idx, %row, %N;
    add.u32 %idx, %idx, %k;
    cvt.u64.u32 %addr, %idx;
    shl.b64 %addr, %addr, 1;                // *sizeof(fp16)
    add.u64 %addr, %A, %addr;
    ld.global.f16 %a, [%addr];

    // ---- Load B[k, col] ----------------------------------------------------
    mul.lo.u32 %idx, %k, %N;
    add.u32 %idx, %idx, %col;
    cvt.u64.u32 %addr, %idx;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %B, %addr;
    ld.global.f16 %b, [%addr];

    // ---- Convert to FP32 and accumulate --------------------------------------
    cvt.f32.f16 %af, %a;
    cvt.f32.f16 %bf, %b;
    fma.rn.f32 %sum, %af, %bf, %sum;

