    add.u32 %idx, %idx, %col;
    cvt.u64.u32 %addr, %idx;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %C, %addr;

    cvt.rn.f16.f32 %c, %sum;
    st.global.f16 [%addr], %c;

